CREATE SCHEMA engagement;
CREATE TABLE engagement.products (id uuid PRIMARY KEY,name varchar(200) NOT NULL,code varchar(32) COLLATE "C" NOT NULL UNIQUE,category varchar(100) NOT NULL,unit_price numeric(16,4) NOT NULL,currency varchar(3) NOT NULL,active boolean NOT NULL,search_name varchar(600) COLLATE "C" NOT NULL,version varchar(32) NOT NULL,modified_at timestamptz(6) NOT NULL,modified_by varchar(256) NOT NULL);
CREATE TABLE engagement.opportunities (id uuid PRIMARY KEY,name varchar(200) NOT NULL,customer_id uuid NOT NULL,customer_name varchar(200) NOT NULL,stage varchar(100) NOT NULL,amount numeric(14,2) NOT NULL,currency varchar(3) NOT NULL,expected_close date NOT NULL,owner varchar(100) NOT NULL,notes varchar(2000) NOT NULL,search_name varchar(600) COLLATE "C" NOT NULL,version varchar(32) NOT NULL,modified_at timestamptz(6) NOT NULL,modified_by varchar(256) NOT NULL);
CREATE TABLE engagement.activities (id uuid PRIMARY KEY,name varchar(200) NOT NULL,customer_id uuid NOT NULL,customer_name varchar(200) NOT NULL,due_date date NOT NULL,kind varchar(100) NOT NULL,status varchar(100) NOT NULL,owner varchar(100) NOT NULL,notes varchar(2000) NOT NULL,search_name varchar(600) COLLATE "C" NOT NULL,version varchar(32) NOT NULL,modified_at timestamptz(6) NOT NULL,modified_by varchar(256) NOT NULL);
CREATE INDEX opportunity_customer ON engagement.opportunities(customer_id);
CREATE INDEX activity_customer ON engagement.activities(customer_id);
